function flexibility(plan){const low=plan.scenarios.low.final.rawGapFte,high=plan.scenarios.high.final.rawGapFte,base=plan.scenarios.base.final.rawGapFte;if(base<=plan.input.actionToleranceFte)return null;const core=Math.max(0,Math.min(low,base)),flex=Math.max(0,high-core);return {coreFte:round(core,2),flexFte:round(flex,2),coreHeadcount:core<=plan.input.actionToleranceFte?0:whole(core)};}
