function actions(plan){const base=plan.scenarios.base.final,items=[];if(base.rawGapFte>.5){items.push({type:'hire',quantity:base.gapHeadcount,textAr:'فجوة موجبة في السيناريو الأساسي: راجع التوظيف الخارجي بعد استنفاد النقل والتطوير الداخلي.',textEn:'Positive base-case gap: review external hiring after internal mobility and development options.'});items.push({type:'build',quantity:base.gapHeadcount,textAr:'حدد المهارات التي يمكن بناؤها داخليًا واربطها بخطة تطوير قبل إنشاء شواغر جديدة.',textEn:'Identify skills that can be built internally and link them to development before creating new vacancies.'});}else if(base.rawGapFte<-.5)items.push({type:'move',quantity:Math.abs(base.gapHeadcount),textAr:'يوجد فائض قدرة محتمل؛ راجع إعادة التوزيع أو الاستنزاف الطبيعي بدل التوظيف.',textEn:'Potential capacity surplus: review redeployment or natural attrition instead of hiring.'});else items.push({type:'hold',quantity:0,textAr:'العرض والطلب قريبان من التوازن وفق الافتراضات الحالية؛ راقب مؤشرات الطلب والإنتاجية.',textEn:'Supply and demand are near balance under current assumptions; monitor demand and productivity indicators.'});return items;}
